Each keystroke makes this input lose focus. Why?

```jsx
function Profile() {
  const [name, setName] = useState('');

  function NameField() {
    return <input value={name} onChange={(e) => setName(e.target.value)} />;
  }

  return <form><NameField /></form>;
}
```

