What happens when `setShow(false)` runs?

```jsx
function Header() {
  const [title] = useState('Home');
  return <h1>{title}</h1>;
}

function App() {
  const [show, setShow] = useState(true);
  const [count] = useState(0);
  return <div>{show && Header()}{count}</div>;
}
```

